insert into public.centre_kinds (key, label_en, label_nl, sort) values
  ('asylum', 'Asylum seekers’ centre', 'Asielzoekerscentrum', 0),
  ('camp', 'Refugee camp', 'Vluchtelingenkamp', 1),
  ('community', 'Community & youth centre', 'Buurt- en jongerencentrum', 2),
  ('school', 'School league', 'Scholencompetitie', 3),
  ('ngo', 'NGO programme', 'Ngo-programma', 4);
insert into public.centres (key, kind_key, name_en, name_nl, city, country, region_key, lng, lat, active_since, active_until, scouts, note_en, note_nl, sort) values
  ('azc-ter-apel', 'asylum', 'Ter Apel registration centre', 'Aanmeldcentrum Ter Apel', 'Ter Apel', 'NL', null, 7.1, 53.0, 2025, null, 2, 'The first stop for most new arrivals in the Netherlands. We run an open training every week and meet young players before they are moved on.', 'De eerste plek voor de meeste nieuwkomers in Nederland. We geven elke week een open training en ontmoeten jonge spelers voordat ze worden overgeplaatst.', 0),
  ('azc-amsterdam', 'asylum', 'Asylum seekers’ centre Amsterdam', 'Azc Amsterdam', 'Amsterdam', 'NL', null, 4.9, 52.4, 2025, null, 3, 'Close to our hub. Players from the centre train with a local amateur club, our scouts follow their matches.', 'Dicht bij onze hub. Spelers uit het azc trainen mee bij een lokale amateurclub, onze scouts volgen hun wedstrijden.', 1),
  ('azc-rotterdam', 'asylum', 'Asylum seekers’ centre Rotterdam', 'Azc Rotterdam', 'Rotterdam', 'NL', null, 4.5, 51.9, 2026, null, 2, 'A Saturday street-football tournament with the neighbourhood, open to every resident of the centre.', 'Een straatvoetbaltoernooi op zaterdag met de buurt, open voor iedere bewoner van het azc.', 2),
  ('azc-zwolle', 'asylum', 'Asylum seekers’ centre Zwolle', 'Azc Zwolle', 'Zwolle', 'NL', null, 6.1, 52.5, 2025, 2026, 1, 'Our pilot location in 2025. The centre has since closed; the scouting network moved with the residents.', 'Onze pilotlocatie in 2025. Het azc is inmiddels gesloten; het scoutingnetwerk verhuisde mee met de bewoners.', 3),
  ('fedasil-brussels', 'asylum', 'Reception centre Brussels', 'Opvangcentrum Brussel', 'Brussels', 'BE', null, 4.4, 50.8, 2026, null, 2, 'Together with a Brussels youth club we organise mixed training sessions for residents aged 13 to 19.', 'Samen met een Brusselse jeugdclub organiseren we gemengde trainingen voor bewoners van 13 tot 19 jaar.', 4),
  ('eae-dusseldorf', 'asylum', 'Initial reception centre Düsseldorf', 'Eerste opvang Düsseldorf', 'Düsseldorf', 'DE', null, 6.8, 51.2, 2026, null, 1, 'Linked to our partner academy in Düsseldorf: residents can join an open trial day each season.', 'Gekoppeld aan onze partneracademie in Düsseldorf: bewoners kunnen elk seizoen meedoen aan een open talentendag.', 5),
  ('kakuma-camp', 'camp', 'Kakuma refugee camp', 'Vluchtelingenkamp Kakuma', 'Kakuma', 'KE', 'kakuma', 34.9, 3.7, 2026, null, 3, 'Weekend camp leagues with hundreds of players. Our scouts are coaches who live in the camp themselves.', 'Kampcompetities in het weekend met honderden spelers. Onze scouts zijn trainers die zelf in het kamp wonen.', 6),
  ('dadaab-camp', 'camp', 'Dadaab refugee complex', 'Vluchtelingencomplex Dadaab', 'Dadaab', 'KE', 'somalia', 40.3, 0.1, 2026, null, 2, 'Home to many Somali families. We work with a girls’ team run by camp teachers.', 'Thuis voor veel Somalische gezinnen. We werken samen met een meidenteam dat door leraren in het kamp wordt geleid.', 7),
  ('zaatari-camp', 'camp', 'Zaatari refugee camp', 'Vluchtelingenkamp Zaatari', 'Mafraq', 'JO', 'syria', 36.3, 32.3, 2025, 2026, 2, 'Our first camp programme for Syrian players. Handed over to a local NGO in 2026, which still shares footage with us.', 'Ons eerste kampprogramma voor Syrische spelers. In 2026 overgedragen aan een lokale ngo, die nog steeds beelden met ons deelt.', 8),
  ('juba-schools', 'school', 'Juba school league', 'Scholencompetitie Juba', 'Juba', 'SS', 'southsudan', 31.6, 4.9, 2025, null, 2, 'A league of twelve secondary schools. Teachers act as scouts and make sure players stay in school.', 'Een competitie van twaalf middelbare scholen. Leraren zijn onze scouts en zorgen dat spelers op school blijven.', 9),
  ('goma-ngo', 'ngo', 'Girls’ & boys’ teams Goma', 'Meiden- en jongensteams Goma', 'Goma', 'CD', 'drc', 29.2, -1.7, 2025, null, 3, 'Run by a local NGO for children displaced by the fighting around Goma.', 'Geleid door een lokale ngo voor kinderen die door de gevechten rond Goma ontheemd zijn.', 10),
  ('dnipro-idp', 'community', 'Youth centre for displaced families', 'Jongerencentrum voor ontheemde gezinnen', 'Dnipro', 'UA', 'ukraine', 35.0, 48.5, 2025, null, 2, 'Indoor training for players whose academies were closed or destroyed.', 'Zaaltraining voor spelers van wie de academie gesloten of verwoest is.', 11);
