insert into public.clubs (key, name, city, country, level_key, league, squads, tier_key, offers, lng, lat, partner_since, placements, note_en, note_nl, sort) values
  ('sc-vechtstad', 'SC Vechtstad', 'Utrecht', 'NL', 'top', 'Eredivisie', 'mf', 'academy_partner', array['housing', 'school', 'language', 'youth'], 5.12, 52.09, 2025, 3, 'A mid-table club that builds on its own academy. Our first partner academy: FCG players live with host families and go to school nearby.', 'Een middenmoter die bouwt op de eigen opleiding. Onze eerste partneracademie: FCG-spelers wonen bij gastgezinnen en gaan in de buurt naar school.', 0),
  ('fc-scheldeoever', 'FC Scheldeoever', 'Antwerp', 'BE', 'top', 'Jupiler Pro League', 'm', 'academy_partner', array['housing', 'language', 'youth', 'trial'], 4.40, 51.22, 2025, 2, 'Fighting relegation, so the minutes are real. The U21 squad takes FCG players for stages of six to twelve weeks.', 'Strijdt tegen degradatie, dus de speelminuten zijn echt. De O21 neemt FCG-spelers op voor stages van zes tot twaalf weken.', 1),
  ('bk-nordhavn', 'Nordhavn BK', 'Copenhagen', 'DK', 'top', 'Superliga · Kvindeligaen', 'mf', 'academy_partner', array['housing', 'school', 'language', 'youth'], 12.59, 55.71, 2025, 2, 'Strong women’s section. Danish lessons from day one, and a welfare officer who speaks Arabic and Ukrainian.', 'Sterke vrouwenafdeling. Vanaf dag één Deense les, en een welzijnsfunctionaris die Arabisch en Oekraïens spreekt.', 2),
  ('sv-rheinufer', 'SV Rheinufer 04', 'Düsseldorf', 'DE', 'second', '2. Bundesliga', 'm', 'academy_partner', array['housing', 'school', 'youth', 'trial'], 6.77, 51.22, 2026, 1, 'Runs an open trial day each season for residents of the initial reception centre in Düsseldorf.', 'Organiseert elk seizoen een open talentendag voor bewoners van de eerste opvang in Düsseldorf.', 3),
  ('atletico-ribeira', 'Atlético Ribeira', 'Porto', 'PT', 'second', 'Liga Portugal 2', 'm', 'academy_partner', array['housing', 'language', 'youth'], -8.61, 41.15, 2026, 1, 'A small club with a big scouting tradition in Africa. Portuguese lessons and an academy house next to the training ground.', 'Een kleine club met een grote scoutingtraditie in Afrika. Portugese les en een academiehuis naast het trainingscomplex.', 4),
  ('as-confluence', 'AS Confluence', 'Lyon', 'FR', 'second', 'Ligue 2 · Seconde Ligue', 'mf', 'academy_partner', array['housing', 'school', 'language', 'youth'], 4.83, 45.76, 2026, 1, 'Both squads train on the same campus. Players combine football with a French vocational programme.', 'Beide selecties trainen op hetzelfde complex. Spelers combineren voetbal met een Franse beroepsopleiding.', 5),
  ('fc-eemland', 'FC Eemland', 'Amersfoort', 'NL', 'second', 'Keuken Kampioen Divisie', 'm', 'scout_access', array['trial', 'youth'], 5.39, 52.16, 2026, 1, 'Uses the portal to scout for its U19 and U21. Usually in the bottom half — and proud of giving young players minutes.', 'Scout via het portaal voor de O19 en O21. Meestal in de onderste helft — en trots op de speeltijd die jonge spelers krijgen.', 6),
  ('ik-fyris-sodra', 'IK Fyris Södra', 'Uppsala', 'SE', 'semipro', 'Division 1 · Elitettan', 'mf', 'scout_access', array['language', 'trial'], 17.64, 59.86, 2026, 0, 'Semi-professional, with a long history of welcoming newcomers. Swedish lessons are part of the deal.', 'Semiprofessioneel, met een lange traditie in het opvangen van nieuwkomers. Zweedse les hoort erbij.', 7),
  ('vv-dinkelstreek', 'VV Dinkelstreek', 'Oldenzaal', 'NL', 'semipro', 'Tweede Divisie', 'm', null, array['trial', 'school'], 6.93, 52.31, 2026, 1, 'A step between amateur and professional football: training four times a week, with time left for school.', 'Een tussenstap tussen amateur- en profvoetbal: vier keer per week trainen, met tijd over voor school.', 8),
  ('rksv-maasoever', 'RKSV Maasoever', 'Venlo', 'NL', 'semipro', 'Derde Divisie', 'm', null, array['trial'], 6.17, 51.37, 2026, 0, 'Plays near the bottom of the Derde Divisie and gives FCG players their first taste of senior football.', 'Speelt onderin de Derde Divisie en laat FCG-spelers voor het eerst proeven aan seniorenvoetbal.', 9),
  ('vv-de-ijsvogels', 'VV De IJsvogels', 'Amsterdam', 'NL', 'amateur', 'Vierde Klasse', 'mf', null, array['trial', 'language'], 4.92, 52.38, 2025, 4, 'Our neighbourhood club near the hub. Residents of the Amsterdam asylum centre train here every week; volunteers help with Dutch.', 'Onze buurtclub vlak bij de hub. Bewoners van het azc Amsterdam trainen hier elke week mee; vrijwilligers helpen met Nederlands.', 10),
  ('vv-westerwolde', 'VV Westerwolde', 'Ter Apel', 'NL', 'amateur', 'Eerste Klasse', 'm', null, array['trial'], 7.06, 52.88, 2025, 2, 'Opens its pitches to new arrivals from the Ter Apel registration centre. Often the very first club a player joins in Europe.', 'Stelt de velden open voor nieuwkomers uit aanmeldcentrum Ter Apel. Vaak de allereerste club van een speler in Europa.', 11),
  ('sv-charlois-zuid', 'SV Charlois Zuid', 'Rotterdam', 'NL', 'amateur', 'Hoofdklasse', 'mf', null, array['trial', 'school'], 4.47, 51.88, 2026, 1, 'Hosts our Saturday street tournament and has a girls’ team that welcomed three players from the Rotterdam centre.', 'Ontvangt ons zaterdagse straattoernooi en heeft een meidenteam dat drie speelsters uit het azc Rotterdam verwelkomde.', 12),
  ('royal-zenne', 'Royal Zenne FC', 'Brussels', 'BE', 'amateur', 'Eerste Provinciale', 'm', null, array['trial', 'language'], 4.33, 50.85, 2026, 1, 'A Brussels youth club running mixed training sessions with the reception centre for players aged 13 to 19.', 'Een Brusselse jeugdclub die met het opvangcentrum gemengde trainingen geeft voor spelers van 13 tot 19 jaar.', 13),
  ('spvgg-lohausen', 'SpVgg Lohausen-Nord', 'Düsseldorf', 'DE', 'amateur', 'Oberliga Niederrhein', 'm', null, array['trial'], 6.75, 51.28, 2026, 0, 'The feeder club of SV Rheinufer: players who are not ready for a stage yet get regular matches here.', 'De opleidingsclub van SV Rheinufer: spelers die nog niet klaar zijn voor een stage spelen hier wekelijks wedstrijden.', 14);
